import{_ as l,C as n,o as d,c as i,j as e,a,E as r,a3 as o}from"./chunks/framework.D4-ViStF.js";const x=JSON.parse('{"title":"断占总诀篇之一：观梅数诀","description":"汇集方位、变卦、体用、衰旺与克应，形成断占的总纲。","frontmatter":{"title":"断占总诀篇之一：观梅数诀","description":"汇集方位、变卦、体用、衰旺与克应，形成断占的总纲。","category":"学习计划 · 第三阶段"},"headers":[],"relativePath":"yijing/meihua-yishu/duan-zhan-zong-jue/plum-blossom-formulas.md","filePath":"yijing/meihua-yishu/duan-zhan-zong-jue/plum-blossom-formulas.md","lastUpdated":1787738987000}'),p={name:"yijing/meihua-yishu/duan-zhan-zong-jue/plum-blossom-formulas.md"};function h(c,t,b,g,u,m){const s=n("DaoTextReading");return d(),i("div",null,[t[0]||(t[0]=e("h1",{id:"【断占总诀篇之一】八卦方位·观梅数诀序·变卦式·占卦诀·体用互变·生克·衰旺·动静·坐端·克应",tabindex:"-1"},[a("【断占总诀篇之一】八卦方位·观梅数诀序·变卦式·占卦诀·体用互变·生克·衰旺·动静·坐端·克应 "),e("a",{class:"header-anchor",href:"#【断占总诀篇之一】八卦方位·观梅数诀序·变卦式·占卦诀·体用互变·生克·衰旺·动静·坐端·克应","aria-label":'Permalink to "【断占总诀篇之一】八卦方位·观梅数诀序·变卦式·占卦诀·体用互变·生克·衰旺·动静·坐端·克应"'},"​")],-1)),t[1]||(t[1]=e("blockquote",null,[e("p",null,"卷三是全书的综合收官。本篇将前两卷的理论系统化为一套完整的断占总诀，并以变卦式八则为实战示范。")],-1)),t[2]||(t[2]=e("hr",null,null,-1)),t[3]||(t[3]=e("h2",{id:"📜-原文",tabindex:"-1"},[a("📜 原文 "),e("a",{class:"header-anchor",href:"#📜-原文","aria-label":'Permalink to "📜 原文"'},"​")],-1)),r(s,{colophon:"观梅数诀 · 变卦式 · 诸诀",tone:"ink",sections:[{id:"sec-01",label:"八卦方位图 (原书此处有图，方位如下)",showLabel:!0,sentences:[["离南  巽东南 坤西南 震东 兑西 艮东北 乾西北 坎北"]]},{id:"sec-02",label:"观梅数诀序",showLabel:!0,sentences:[[{text:"嗟呼",glossary:"g01"},"，《易》岂易言哉！"],["盖《易》之为书，至精微，至玄妙。"],["然数者，不外乎易理也。"],["有先后天之殊，有",{text:"叶音取音",glossary:"g02"},"之辨，明",{text:"忧虞",glossary:"g03"},"得失之机，取互变迟速之应。"]]},{id:"sec-02-1",label:"",showLabel:!0,sentences:[["数有前定，祸福难测。"]]},{id:"sec-02-2",label:"",showLabel:!0,sentences:[["易理",{text:"灼然",glossary:"g04"},"可察，予求得先天、玄黄、灵应诸篇，外采易辞，曰：观梅数诀，列图明五行生克衰旺之理，分例指避凶趋吉之道。"],["后学群子幸鉴焉。"]]},{id:"sec-02-3",label:"",showLabel:!0,sentences:[["易辞曰：易有太极，是生两仪，两仪生四象，四象生八卦，八卦生万物。"]]},{id:"sec-02-4",label:"",showLabel:!0,sentences:[["邵子曰：一分为二，二分为四，四分为八也。"]]},{id:"sec-02-5",label:"",showLabel:!0,sentences:[["说卦传曰：易",{text:"逆数",glossary:"g05"},"也。"]]},{id:"sec-02-6",label:"",showLabel:!0,sentences:[["邵子曰：干一、兑二、离三、震四、巽五、坎六、艮七、坤八，自干至坤，皆得未生之卦，若逆推四时之比也。"],["后天六十四卦仿此。"]]},{id:"sec-03",label:"八卦定阴阳次序",showLabel:!0,sentences:[["干为父，震长男，坎中男，艮少男；坤为母，巽长女，离中女，兑少女。"]]},{id:"sec-04",label:"变卦式八则",showLabel:!0,sentences:[["离卦初爻，阳动变阴，变艮卦兑金，为少女，离火克之。"]]},{id:"sec-04-1",label:"",showLabel:!0,sentences:[["巽为股，干金克之，曰：伤股。"],["得艮土生，入兑金，断曰：不至于死。"],["体用于变爻，作动静取之。"],["动者为用，静者为体。"],["木是用爻，断出软物，文章之体也。"],["此卦断出是铁器之物。"]]},{id:"sec-04-2",label:"",showLabel:!0,sentences:[["此卦乃用金体火，夏火得旺，能出土，必是土物也。"],["用爻属木变火，体卦属金。"],["四爻变卦成艮，土能生金，断出是铁。"],["此卦非金是石，断是破磁盘也。"]]},{id:"sec-04-3",label:"",showLabel:!0,sentences:[["本卦得泽火革，为少女，近物为口，远取羊。"],["内离为中女，近日，远取雉。"],["初爻变艮卦为土，土能生金，则扶起兑金之妹。"],["次除去初爻，移上四爻，又成巽木，断得伤股之灾。"],["得初爻变艮土生兑金，是故有救而不至于死也。"]]},{id:"sec-04-4",label:"",showLabel:!0,sentences:[["近取诸身，干头、坤腹、震足、巽股、坎耳、离目、兑口、艮手，人身；远取诸物，干马、坤牛、震龙、巽鸡、坎豕、离雉、艮狗、兑羊，畜道。"],["盖卦是体生，而乃泄已之气，其财空望。"],["次得离卦属火，能克金。"],["其日午时，客来食去酒，返自消耗也。"]]},{id:"sec-05",label:"占卦诀",showLabel:!0,sentences:[["又如占卦问吉事，则看卦中有生体之卦，则吉事应之必速。"],["便看生体之卦，于八卦时序类决其日时。"],["如生体是用卦，则事即成。"],["生体是互卦，则渐成。"],["生体是变卦，则稍迟耳。"]]},{id:"sec-05-1",label:"",showLabel:!0,sentences:[["若有生体之卦，又有克体之卦，则事有阻节，好中不足产。"],["便看克体卦气阻于几日，若干克体，阻一日，兑克体，阻二日之类推之。"],["如占吉事，无生体之卦，有克体之卦，则事不谐矣。"],["无克体之卦，则吉事必可成就矣。"]]},{id:"sec-05-2",label:"",showLabel:!0,sentences:[["又如占不吉之事，卦中有生体之卦，则有救无害；如无生体之卦，事必不吉矣。"],["若以日期而论，看卦中有生体之卦，则事应于生体卦气之日；有克体之卦，则事败于克体卦气之日。"],["要在活法取用也。"]]},{id:"sec-06",label:"体用互变之诀",showLabel:!0,sentences:[["大凡占卜，以体为其主，互用变皆为应。"],["卦用最紧，互次之，变卦又次之。"],["故曰用为占之即应，互为中间之应，变为事占之终应。"]]},{id:"sec-06-1",label:"",showLabel:!0,sentences:[["然互卦则分其有体之互，有用之互。"],["如体在上，则上互为体之互，下互为用之互，体卦在下，则下互为体之互，上互为用之互。"],["体互最紧，用互次之。"]]},{id:"sec-06-2",label:"",showLabel:!0,sentences:[["例如观梅恒卦，互兑、干，兑为体，互见女子折花。"],["若干为体，互则老人折花矣。"],["盖兑、干皆克体，但取兑而不取干，此体互用之分。"]]},{id:"sec-06-3",label:"",showLabel:!0,sentences:[["大凡占卦，变卦克体，事于末后，必有不吉。"],["变生体及比和，则事事临终有吉利。"],["此用互变之诀也。"]]},{id:"sec-07",label:"体用生克之诀",showLabel:!0,sentences:[["占卦即以卦分体用互变，即以五行之理断其吉凶。"],["然生克之理，于内卦体用互变，一定之生克。"],["若外卦，则须明其真生真克之五行，以分轻重，则祸福立应。"],["何也？"]]},{id:"sec-07-1",label:"",showLabel:!0,sentences:[["假如干、兑之金为体，见火则克，然有真火之体，有火之形色。"],["真火能克金，形色则不能克。"],["能克则不吉，不能克则不顺而已。"],["盖见炉中火，窑灶之火，真火也。"],["烈焰",{text:"巨炷",glossary:"g09"},"，真火也。"],["干、兑为体，遇之不吉。"],["若色之红紫，形之中虚，",{text:"槁木",glossary:"g08"},"之离，日火之火，则灶之形色，非真火也，干、兑之体，不为深忌。"]]},{id:"sec-07-2",label:"",showLabel:!0,sentences:[["又若一盏之灯，一炬之烛，虽曰真火，微细而轻，小不利耳。"],["又若震、巽之木体，遇金则克，然",{text:"钗钏",glossary:"g06"},"之金，",{text:"金铂",glossary:"g07"},"之金，成锭之银，杯盘之银，与器之锡，",{text:"琐屑",glossary:"g10"},"之钢铁皆金也。"]]},{id:"sec-07-3",label:"",showLabel:!0,sentences:[["此等之金，岂能克木？"],["木之所忌者，快刀锐刃，巨斧大锯。"],["震、巽之体，值之必有不吉。"],["又若离火为体，见真水能克。"],["然但见色之黑者，见体之湿者，与夫血之类，皆坎之属，终忌而不深害也。"],["余卦为体，所值外应，克者皆以轻重断之。"],["若夫生体之卦，亦当分辨。"]]},{id:"sec-07-4",label:"",showLabel:!0,sentences:[["土与瓦器皆坤土，金遇之，土能生金，瓦不能生也。"],["树木柴薪，皆木也。"],["离火值之，柴薪生火之捷，树木之末伐者，生炎之迟也。"],["木为体，真水生木之福重，如豕如血虽坎之属，生木之类轻也。"],["其余五行生克，并以类以推之。"]]},{id:"sec-08",label:"体用衰旺之诀",showLabel:!0,sentences:[["凡体卦宜乘旺，克体之卦宜衰。"],["盖体卦之气，如春木、夏火、秋金、冬水、四季之月土，此",{text:"得令",glossary:"g14"},"之卦，乘旺之气，虽有他卦克之，亦无大害。"]]},{id:"sec-08-1",label:"",showLabel:!0,sentences:[["用互变卦，乘旺皆吉，但不要克体之卦气旺。"],["而体卦气衰是不吉之占。"],["占者有此，若问病必死，问讼必败。"]]},{id:"sec-08-2",label:"",showLabel:!0,sentences:[["若非问讼与病而常占，则防有官病之事。"],["末临其期，在于克体卦气之月日也。"],["若卦体旺而复有生体之卦，吉事之来，可",{text:"刻期",glossary:"g11"},"而至矣。"],["若内卦外卦有生体者，体卦虽衰，亦无大害也。"]]},{id:"sec-08-3",label:"",showLabel:!0,sentences:[["内外并也生体，虽体之",{text:"卦党",glossary:"g13"},"多，皆是衰卦，终不吉也。"],["故体用之卦，必须详其盛衰也。"]]},{id:"sec-09",label:"体用动静之诀",showLabel:!0,sentences:[["占卦体用互变既分，必以内外之卦察其动不动。"],["不动不占，亦不断。"],["其吉凶悔吝，生乎动也。"]]},{id:"sec-09-1",label:"",showLabel:!0,sentences:[["夫体卦为静，互卦为静，用卦变卦则动也，此内卦之动静也。"],["以外卦言之，方应之卦，天地地理之卦，应皆静，若人事之应，器物之类，则有动者矣。"]]},{id:"sec-09-2",label:"",showLabel:!0,sentences:[["器物本静，人持其器物而来，则动矣。"],["若干马、坤牛，皆动者矣。"],["盖水之井沼，土之山岩石，皆静者矣。"],["人汲水担水而前，水之动也。"],["又人持石负土而前，土之动也。"]]},{id:"sec-09-3",label:"",showLabel:!0,sentences:[["于外卦之应，观其动静而审其吉凶，动而吉者，应吉之速；动而凶者，应凶之速；不动而应者，吉凶之末见也。"],["此则外卦体用之动静也。"]]},{id:"sec-09-4",label:"",showLabel:!0,sentences:[["若夫起卦之动静，亦以我之中静而观其动者而占之。"],["如雀之争坠，如牛鸡之衰鸣，如枯木之坠，皆物之动者，我以静而占之也。"]]},{id:"sec-09-5",label:"",showLabel:!0,sentences:[["又若我坐，则事应之迟；我行而事应之速；我立而半迟半速，此皆动静之理也。"]]},{id:"sec-10",label:"占卜坐端之诀",showLabel:!0,sentences:[[{text:"坐端",glossary:"g12"},"之诀，以我之所坐为中，八位列于八方，占卦决断之。"],["须虚心待应，坐而端之，察其八卦八方应兆，以为占卜事端之应。"],["随其方卦有生克之应者，以定所占之家吉凶也。"]]},{id:"sec-10-1",label:"",showLabel:!0,sentences:[["如干上有土生之，或干宫有诸吉兆，则尊长老人分上，见吉庆大事。"],["若干上有火克之，或有凶兆，则主长上老人有忧。"]]},{id:"sec-10-2",label:"",showLabel:!0,sentences:[["坤有火生之，或坤上有吉兆，则主母亲分上或主阴人有吉利之喜。"],["坤宫见克，或有凶兆，则主老母阴人有灾厄。"]]},{id:"sec-10-3",label:"",showLabel:!0,sentences:[["震宫有水生之，及东方震宫有吉兆，则喜在长子长孙；见克而或见凶，则长子长孙不利。"]]},{id:"sec-10-4",label:"",showLabel:!0,sentences:[["坎宫宜见五金及有吉利之谶，则喜在中男之位；若土克，若见凶，则忧在中男矣。"]]},{id:"sec-10-5",label:"",showLabel:!0,sentences:[["离宫喜木生之，或有可喜之应，则中女有喜；若遇克或见凶，则中女有厄矣。"]]},{id:"sec-10-6",label:"",showLabel:!0,sentences:[["艮为少男之位，宜火生之，见吉则少男之喜；若遇克，或见凶，则灾及少男。"],["问产必不育矣。"]]},{id:"sec-10-7",label:"",showLabel:!0,sentences:[["兑为少女，土宜生之，见吉则少女有喜，或有欢悦之事。"],["若问病，如干卦受克，病在头。"]]},{id:"sec-10-8",label:"",showLabel:!0,sentences:[["坤宫见克，病在腹，推之震足、巽股、离目、坎耳及血、艮手指、兑口齿，于其克者定见其病。"]]},{id:"sec-10-9",label:"",showLabel:!0,sentences:[["至于八端之中，有奇占巧卜者，则在乎人。"],["此引其端为之例也。"]]},{id:"sec-11",label:"占卜克应之诀",showLabel:!0,sentences:[["克应者，所谓",{text:"克期应验",glossary:"g15"},"也。"],["占卜之道，无此诀，则吉凶成败之事不知应于何时。"],["故克应为卦之切要也。"]]},{id:"sec-11-1",label:"",showLabel:!0,sentences:[["然克则最难，有以数而克之者，有以理而克之者，皆要论也。"],["以数而",{text:"刻期",glossary:"g11"},"，必详其理，如算屋宅之初创，男女之始婚，坟之方葬，器物之新置，俱以年月日时加事物之数而起卦。"],["卦成，则于体用互变之中，视",{text:"全卦之数",glossary:"g16"},"，以为约定之期，审其事端之迟速而刻之，如屋宅坟墓永久者也。"],["屋宅则以",{text:"全卦之数",glossary:"g16"},"刻其期。"]]},{id:"sec-11-2",label:"",showLabel:!0,sentences:[["如屋宅之终应，盖屋宅有朽坏之期也。"],["坟墓亦有损坏，然占墓但占吉凶，不计成败也。"],["男女之婚，远亦不过数年。"],["年内之事，",{text:"全卦之数",glossary:"g16"},"可决，又不如屋宅之久也。"],["然婚姻亦不过卜其吉凶，不必刻其期也。"],["若吉凶之期，但以生体及比和之年月为吉期，克体之年月为不吉之期也。"]]},{id:"sec-11-3",label:"",showLabel:!0,sentences:[["器物之占，则金石之质终远，草木之质终不久也。"],["远者，以",{text:"全卦之数",glossary:"g16"},"为年期；近者，以",{text:"全卦之数",glossary:"g16"},"为月期。"],["又近者，以全卦为日期也。"],["如置砚，则",{text:"全卦之数",glossary:"g16"},"为岁。"],["计笔墨亦可以全卦为岁计。"],["笔墨之小者，以日卦之数可也。"],["此器物",{text:"刻期",glossary:"g11"},"之占也。"]]},{id:"sec-11-4",label:"",showLabel:!0,sentences:[["如先天观梅与牡丹二花，俱旦夕之事，故以卦理推，则不必决其远日也。"],["如后天老年、少年、鸡牛之占，以方卦物卦之数合而计之。"],["老少、鸡牛之占，亦只可以日计也。"],["若永远之占，则以日为月，以月为年矣。"],["占者详吉，必又寻常之占事",{text:"刻期",glossary:"g11"},"，则于全卦中细观生体之卦为吉，应决期克体之卦为凶。"],["应之期远，则以年，近则以月，又近则以日也。"]]},{id:"sec-11-5",label:"",showLabel:!0,sentences:[["如问求名则干为体，看卦中有坤、艮，则断其辰、戌、丑、未之土月日。"],["盖干、兑，金体也。"],["此为吉事生体之应。"]]},{id:"sec-11-6",label:"",showLabel:!0,sentences:[["若问病而干卦为体，则看卦中有离，又看卦中无坤、艮，及有凶犯，则其体死于巳午火日，此克体为凶事之期也。"],["又若问行人，以生体之日为归期，无生体比和之日，则归必迟。"],["若此例者，具难尽载，学者审焉。"]]}],glossary:[{id:"g01",term:"嗟呼",pinyin:"jiē hū",meaning:"感叹词，唉"},{id:"g02",term:"叶音取音",pinyin:"yè yīn",meaning:"以谐音取象义"},{id:"g03",term:"忧虞",pinyin:"yōu yú",meaning:"忧虑，虞：预料到的忧患"},{id:"g04",term:"灼然",pinyin:"zhuó rán",meaning:"明显，清楚可见"},{id:"g05",term:"逆数",pinyin:"nì shǔ",meaning:"逆推，从果推因，从后推前"},{id:"g06",term:"钗钏",pinyin:"chāi chuàn",meaning:"钗：发钗；钏：手镯，皆为首饰"},{id:"g07",term:"金铂",pinyin:"jīn bó",meaning:"金箔，极薄的金片"},{id:"g08",term:"槁木",pinyin:"gǎo mù",meaning:"枯干的木头"},{id:"g09",term:"巨炷",pinyin:"jù zhù",meaning:"粗大的蜡烛或火炬"},{id:"g10",term:"琐屑",pinyin:"suǒ xiè",meaning:"细碎零散"},{id:"g11",term:"刻期",pinyin:"kè qī",meaning:"确定期限，克期应验"},{id:"g12",term:"坐端",pinyin:"zuò duān",meaning:"端坐观察，以所坐方位为中心取应"},{id:"g13",term:"卦党",pinyin:"guà dǎng",meaning:"与体卦同五行的卦，即体卦的同盟"},{id:"g14",term:"得令",pinyin:"dé lìng",meaning:"当令，当时令之旺气"},{id:"g15",term:"克期应验",pinyin:"—",meaning:"在预定的时间节点上应验"},{id:"g16",term:"全卦之数",pinyin:"—",meaning:"全卦六爻的综合数值，用于推算期限"}],"aria-label":"观梅数诀原文"}),t[4]||(t[4]=o("",135))])}const q=l(p,[["render",h]]);export{x as __pageData,q as default};
